<fieldset class="grid gap-4 rounded-lg bg-slate-50 p-4 md:grid-cols-3"><label class="text-sm">Processing service<select required name="steps[{{ $index }}][processing_service_id]" class="mt-1 block w-full rounded-lg border border-line bg-white p-2"><option value="">Choose service</option>@foreach($services as $s)<option value="{{ $s->id }}" @selected(($step['processing_service_id']??null)==$s->id)>{{ $s->name }}</option>@endforeach</select></label>@foreach(['input_item_id'=>'Input fabric / item','output_item_id'=>'Output fabric / item'] as $field=>$label)<label class="text-sm">{{ $label }}<select required name="steps[{{ $index }}][{{ $field }}]" class="mt-1 block w-full rounded-lg border border-line bg-white p-2"><option value="">Choose item</option>@foreach($items as $item)<option value="{{ $item->id }}" @selected(($step[$field]??null)==$item->id)>{{ $item->sku }} · {{ $item->name }} · {{ $item->baseUnit->code }}</option>@endforeach</select></label>@endforeach<label class="text-sm">Planned yield ratio<input required name="steps[{{ $index }}][planned_yield_ratio]" value="{{ $step['planned_yield_ratio']??'1' }}" class="mt-1 block w-full rounded-lg border border-line bg-white p-2"></label><label class="text-sm">Normal loss fraction (0.05 = 5%)<input required name="steps[{{ $index }}][permitted_normal_loss_fraction]" value="{{ $step['permitted_normal_loss_fraction']??'0' }}" class="mt-1 block w-full rounded-lg border border-line bg-white p-2"></label><button type="button" onclick="this.closest('fieldset').remove()" class="self-end p-2 text-left text-xs text-slate-500">Remove stage</button></fieldset>